package com.hotel.hotel_backend.service;
import com.hotel.hotel_backend.model.Hotel;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;
@Service public class AiService {
 private final String apiKey,model,baseUrl;private final RestClient client;
 public AiService(@Value("${app.ai.api-key:}") String apiKey,@Value("${app.ai.model:gpt-4o-mini}") String model,@Value("${app.ai.base-url:https://api.openai.com/v1}") String baseUrl){this.apiKey=apiKey;this.model=model;this.baseUrl=baseUrl;this.client=RestClient.builder().baseUrl(baseUrl).build();}
 public boolean isEnabled(){return apiKey!=null&&!apiKey.isBlank();}
 public String summarize(String userPrompt,List<Hotel> hotels){String facts=hotels.stream().map(h->h.getName()+" | city="+h.getCity()+" | location="+h.getLocation()+" | starting price INR "+h.getStartingPrice()+" | rating "+h.getRating()).reduce((a,b)->a+"\n"+b).orElse("No hotels");if(!isEnabled())return "Based on your request, these are matching approved hotels from our database. Compare the listed starting prices; final room availability and price must be confirmed for your dates.";try{Map<String,Object> body=Map.of("model",model,"temperature",0.2,"messages",List.of(Map.of("role","system","content","You are StayFinder's hotel assistant. Recommend only properties and facts in the supplied database records. Never invent availability, amenities, prices, discounts or policies. State that prices are starting prices and date availability must be confirmed."),Map.of("role","user","content","User request: "+userPrompt+"\nVerified database records:\n"+facts)));Map<?,?> response=client.post().uri("/chat/completions").contentType(MediaType.APPLICATION_JSON).header("Authorization","Bearer "+apiKey).body(body).retrieve().body(Map.class);List<?> choices=(List<?>)response.get("choices");Map<?,?> choice=(Map<?,?>)choices.get(0);Map<?,?> message=(Map<?,?>)choice.get("message");return String.valueOf(message.get("content"));}catch(Exception ex){return "I found matching hotels in the database. AI text generation is temporarily unavailable; the hotel list below is still based on database records.";}}
}
